// Импорт обязателен и не случаен: он делает файл **модулем**.
//
// Без него `declare module 'react'` объявляет React заново — то есть заменяет
// настоящие типы пустышкой, и разваливается вся витрина. Ровно эту ловушку
// карта v66 уже проходила с `react-router`; я наступил на неё второй раз, уже
// с самим React (Д5 карты v75).
import 'react';

/**
 * Собственные свойства оформления (`--x-…`) в атрибуте `style`.
 *
 * Мы задаём их прямо в разметке — так шапки форм переключают цвета между
 * светлой и тёмной темой. Но в объявлении React у `style` перечислены только
 * известные свойства, и каждое `'--x-…': …` считалось ошибкой.
 *
 * Расширение разрешает ровно то, что уже работает: ключ, начинающийся с двух
 * дефисов. Обычные свойства по-прежнему проверяются.
 */
declare module 'react' {
  interface CSSProperties {
    [key: `--${string}`]: string | number | undefined;
  }
}
